<section class="narrow-page"><a class="back-link" href="<?= e(url(['page' => 'feed'])) ?>"><i class="bi bi-arrow-left"></i> Back to your feed</a><div class="section-heading"><div><span class="eyebrow">Make it yours</span><h1>Edit your post</h1></div></div>
    <form class="composer edit-composer" action="<?= e(url(['page' => 'post-update'])) ?>" method="post" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) $post['id'] ?>"><label class="field-label" for="post-content">Your words</label><textarea id="post-content" name="content" rows="7" maxlength="2000"><?= e($post['content']) ?></textarea><div class="image-preview" data-image-preview data-original-src="<?= !empty($post['image']) ? e('public/uploads/' . $post['image']) : '' ?>"<?= empty($post['image']) ? ' hidden' : '' ?>><?php if (!empty($post['image'])): ?><img src="public/uploads/<?= e($post['image']) ?>" alt="Current post image"><?php else: ?><img alt="Selected photo preview"><?php endif; ?><button class="image-preview-clear" type="button" data-clear-image aria-label="Remove selected photo" hidden><i class="bi bi-x-lg"></i></button></div><div class="composer-bottom"><label class="file-pick"><i class="bi bi-image"></i><span>Replace photo</span><input type="file" name="image" accept="image/jpeg,image/png,image/webp,image/gif"></label><label class="visibility-select"><i class="bi bi-shield-lock"></i><select name="visibility" aria-label="Post audience"><option value="public" <?= $post['visibility'] === 'public' ? 'selected' : '' ?>>Public</option><option value="followers" <?= $post['visibility'] === 'followers' ? 'selected' : '' ?>>Friends only</option><option value="private" <?= $post['visibility'] === 'private' ? 'selected' : '' ?>>Only me</option></select></label><button class="button button-primary" type="submit">Save changes <i class="bi bi-check2"></i></button></div></form>
